// Resolves the tool guide's cherry-pick conflicts: HEAD's plain-English
// structure, with the picked commit's deferral content ported into it.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const path = process.argv[2];
const frag = name => readFileSync(join(here, name), 'utf8').replace(/\r\n/g, '\n').trimEnd().split('\n');
const lines = readFileSync(path, 'utf8').replace(/\r\n/g, '\n').split('\n');

const replaceLine = (block, prefix, replacement) => {
  const index = block.findIndex(line => line.startsWith(prefix));
  if (index < 0) throw new Error('missing line: ' + prefix);
  block.splice(index, 1, ...replacement);
};

const handlers = [
  ours => ours, // evidence list: the picked loading text lands in the next block
  ours => {
    replaceLine(ours, '**How tools are loaded for now.**', frag('frag-loading.md'));
    replaceLine(ours, 'The conclusion is that a definition adds cost', frag('frag-conclusion.md'));
    replaceLine(ours, '**Deferral, when the measurements say so.**', frag('frag-deferral.md'));
    return ours;
  },
  ours => {
    const from = 'All of them load on every turn until the measurements under [tool budget and tool shape](#tool-budget-and-tool-shape) justify deferral. The toolsets below are the groups that would be deferred together when that day comes. Until then they only group tools for naming and for delivery.';
    const to = 'The tools that are implemented follow the loading policy under [tool budget and tool shape](#tool-budget-and-tool-shape). The toolsets below also include future capabilities. Those are not advertised until they are implemented.';
    if (ours.length !== 1 || !ours[0].includes(from)) throw new Error('catalog intro changed');
    return [ours[0].replace(from, to)];
  },
  existsSync(join(here, 'frag-toolsets.md')) ? () => frag('frag-toolsets.md') : null,
];

const out = [];
let conflict = 0;
for (let i = 0; i < lines.length; ++i) {
  if (!lines[i].startsWith('<<<<<<< ')) { out.push(lines[i]); continue; }
  const middle = lines.indexOf('=======', i);
  const end = lines.findIndex((line, at) => at > middle && line.startsWith('>>>>>>> '));
  const handler = handlers[conflict++];
  if (handler) out.push(...handler(lines.slice(i + 1, middle)));
  else out.push(...lines.slice(i, end + 1));
  i = end;
}
if (conflict !== 4) throw new Error('expected 4 conflicts, saw ' + conflict);
writeFileSync(path, out.join('\n'));
console.log('resolved', handlers.filter(Boolean).length, 'of', conflict);

